import React from "react";
import "./HomePage.css"
import { Link, useNavigate } from "react-router-dom";

export default function HomePage() {
   const navigate = useNavigate();
    const token = localStorage.getItem("token");
  
    const startCoding = () => {
      if (token) {
        navigate("/editor");
      } else {
        navigate("/login");
      }
    };
  
  return (
    <section>

 <section id="homePage" className="homepage">
      <div className="hero">
        <div className="hero-text">
          <h1 className="title">
            Welcome to <span className="accent">DailyCode</span>
          </h1>

          <p className="subtitle">
            🚀 Daily Coding Challenges — Short tasks in Python, JavaScript, C++, Java and more.{" "}
            <strong>Levels:</strong> Easy / Medium / Hard
          </p>

          <div className="cta-row">
            <button className="cta">Start Coding →</button>
             <button onClick={startCoding}>
        Start Coding
      </button>
            <a href="#" className="learn">Learn more</a>
          </div>
        </div>
      

      {!token && (
        <>
          <Link to="/login">Login</Link>
          <Link to="/signup">Signup</Link>
        </>
      )}
        <div className="hero-image">
          <img
            src="https://media.giphy.com/media/qgQUggAC3Pfv687qPC/giphy.gif"
            alt="Developer at work"
          />
        </div>
      </div>
    </section>


      

     
    </section>
  );
}
